'use strict';
const $=s=>document.querySelector(s);
const style=document.createElement('link');style.rel='stylesheet';style.href='poster-v2.css';document.head.append(style);
const exportStyle=document.createElement('link');exportStyle.rel='stylesheet';exportStyle.href='poster-export.css';document.head.append(exportStyle);
const p={name:'小满',age:'35',city:'北京',height:'165',weight:'50',school:'北京大学硕士',job:'产品经理',industry:'科技互联网',title:'高级产品经理',income:'30—50万元／年 · 税前',assets:'本人净资产300—500万元 · A7',bio:'喜欢运动、看展，也愿意认真听你分享。',animal:'羊',stem:'戊土',wantedAnimals:['马','兔'],wantedStems:['丙火','丁火'],hobbies:['羽毛球','看展','陶艺']};
const animals=[...'鼠牛虎兔龙蛇马羊猴鸡狗猪'],stems=['甲木','乙木','丙火','丁火','戊土','己土','庚金','辛金','壬水','癸水'];
const options=['羽毛球','网球','乒乓球','游泳','徒步','看展','摄影','陶艺','烘焙','桌游','逛书店','音乐现场'];
const required=['age','height','weight','school','job','industry','title','income','assets'];
const labels={name:'昵称',age:'年龄',city:'城市',height:'身高（cm）',weight:'体重（kg）',school:'学校与学历',job:'职业',industry:'行业',title:'职级 / Title',income:'税前年收入区间',assets:'本人资产区间、A几及负债口径',bio:'一句自我介绍'};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function posterTop(t){return `<div class="topline"><span class="logo">runae.</span><span>${t}</span></div>`;}
function identity(){return `<div class="identity"><span class="person-name">${esc(p.name)}</span><span class="meta">${esc(p.city)} · 属${esc(p.animal)} · ${esc(p.stem)}</span></div>`;}
function essentials(){return `<div class="essentials">${[['年龄',p.age+'岁'],['身高',p.height+'cm'],['体重',p.weight+'kg'],['学校学历',p.school],['职业',p.job],['职级 / Title',p.title],['行业',p.industry],['年收入',p.income],['本人资产',p.assets]].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`;}
function preference(){return `<div class="preference-strip"><span>想认识的生肖</span><b>${p.wantedAnimals.map(t=>'属'+esc(t)).join(' / ')}</b><span>日主</span><b>${p.wantedStems.map(esc).join(' / ')}</b></div>`;}
function hobbyLine(){return `<p class="poster-hobbies"><span>想和你一起</span> ${p.hobbies.map(esc).join(' · ')}</p>`;}
function bottom(cta='申请认识我',copy='输入出生信息，查日主，也生成一张你的交友卡。'){return `<div class="bottom"><div class="cta"><span>${cta}</span><span class="arrow">↗</span></div><p class="secondary">${copy}</p><p class="fine">虚构示例 · 资料自填未核验 · 找人方向为演示偏好，未实际合盘<br>传统文化参考 · 原始生辰不公开 · 当前无真实报名链接</p></div>`;}
function render(){
 const top=posterTop;
 const specs=[
  {type:'a',label:'01 · 五行缘分型',hint:'五行找人＋完整个人条件',body:`${top('FIND YOUR ELEMENT PEOPLE')}<h2>我是<span class="accent">${esc(p.stem)}</span>，<br>想认识<span class="accent">${esc(p.wantedStems[0])}</span>的你。</h2><div class="element-visual"><svg viewBox="0 0 520 90" aria-hidden="true"><ellipse cx="260" cy="45" rx="180" ry="34"/><ellipse cx="260" cy="45" rx="180" ry="34" transform="rotate(10 260 45)"/></svg><span class="large-stem">${esc(p.stem[0])}</span></div>${identity()}${preference()}${essentials()}<p class="intro-copy">${esc(p.bio)}</p>${hobbyLine()}${bottom()}`},
  {type:'b',label:'02 · 个人亮点型',hint:'学校、职业、收入资产清晰展示',body:`${top('A LITTLE MORE ABOUT ME')}<h2>有自己的生活，<br>也想遇见<span class="accent">同频的你。</span></h2>${identity()}<p class="hero-tag">${esc(p.school)} · ${esc(p.job)}</p>${essentials()}${preference()}<p class="intro-copy">${esc(p.bio)}</p>${hobbyLine()}${bottom('我想认真认识你','找朋友、搭子或对象 · 双方愿意后，再了解完整合盘。')}`},
  {type:'c',label:'03 · 兴趣朋友型',hint:'爱好由本人选择，不固定安排活动',body:`${top('MAKE ROOM FOR A NEW FRIEND')}<h2>想认识你，<br>也想一起<span class="accent">做点什么。</span></h2>${identity()}${preference()}${essentials()}<div class="chosen-activities">${p.hobbies.slice(0,3).map((t,i)=>`<div><span>0${i+1}</span><strong>${esc(t)}</strong><small>这是我自己选择的爱好</small></div>`).join('')}</div>${bottom('从共同的兴趣，开始认识','先认识人，双方同意后，再商量时间、预算和地点。')}`},
  {type:'d',label:'04 · 双人合盘邀请型',hint:'先看个人条件，再邀请私密合盘',body:`${top('AN INVITATION FOR TWO')}<h2>我和你，<br>放在一起<span class="accent">会怎样？</span></h2><div class="pair-art"><div class="circle"><b>${esc(p.stem[0])}</b><span>${esc(p.name)} · 属${esc(p.animal)}</span></div><span class="plus">＋</span><div class="circle"><b>？</b><span>等你一起填写</span></div></div>${essentials()}${preference()}${hobbyLine()}<div class="private-note">各自填写，双方授权后查看；不交换完整生辰。</div>${bottom('接受邀请，看看我们的关系','可以只参与这一次合盘，不必加入公开交友池。')}`}
 ];
 $('#gallery').innerHTML=specs.map((s,i)=>`<section class="design" data-design="${i+1}"><div class="design-label"><b>${s.label}</b><a href="?design=${i+1}" target="_blank">${s.hint} ↗</a></div><div class="poster-frame"><article class="poster ${s.type}">${s.body}</article></div></section>`).join('');
 const params=new URLSearchParams(location.search),chosen=params.get('design');if(['1','2','3','4'].includes(chosen)){document.body.classList.add('single');document.querySelector(`[data-design="${chosen}"]`).classList.add('selected');if(params.has('export'))document.body.classList.add('export');}
}
$('#edit').onclick=()=>{
 const fields=Object.entries(labels).map(([k,label])=>`<label class="field">${label}${required.includes(k)?' *':''}<input name="${k}" value="${esc(p[k])}" maxlength="${k==='bio'?80:65}" ${required.includes(k)||['name','city'].includes(k)?'required':''} ${['age','height','weight'].includes(k)?`type="number" min="${k==='age'?18:k==='height'?100:25}" max="${k==='age'?100:k==='height'?240:250}"`:''}></label>`).join('');
 $('#fields').innerHTML=`<p>九项个人条件必填；父母职业、养老金暂不采集。本设计预览表单中的内容均用于公开海报，正式版按本人选择控制公开范围。</p>${fields}<label class="field">我的生肖<select name="animal" required>${animals.map(a=>`<option ${p.animal===a?'selected':''}>${a}</option>`).join('')}</select></label><label class="field">我的日主<select name="stem" required>${stems.map(s=>`<option ${p.stem===s?'selected':''}>${s}</option>`).join('')}</select></label><fieldset><legend>想认识的生肖 *（可多选）</legend>${animals.map(a=>`<label class="choice"><input type="checkbox" name="wantedAnimals" value="${a}" ${p.wantedAnimals.includes(a)?'checked':''}>${a}</label>`).join('')}</fieldset><fieldset><legend>想认识的日主 *（可多选）</legend>${stems.map(s=>`<label class="choice"><input type="checkbox" name="wantedStems" value="${s}" ${p.wantedStems.includes(s)?'checked':''}>${s}</label>`).join('')}<p>正式版根据完整分析给出建议，再由本人确认；本地修改只改变演示偏好，不会执行真实排盘。</p></fieldset><fieldset><legend>选自己的爱好 *（至少一项）</legend>${options.map(t=>`<label class="choice"><input type="checkbox" name="hobbies" value="${t}" ${p.hobbies.includes(t)?'checked':''}>${t}</label>`).join('')}</fieldset><label class="choice"><input type="checkbox" required>我同意将以上示例内容展示在预览海报上。</label><p id="form-error" role="alert" style="color:#a34f3c"></p>`;
 $('#dialog').showModal();
};
$('#close').onclick=()=>$('#dialog').close();
$('#profile-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);for(const key of ['wantedAnimals','wantedStems','hobbies'])if(!f.getAll(key).length){$('#form-error').textContent='请至少选择一个想认识的生肖、一个日主和一项自己的爱好。';return;}for(const k of required)if(!String(f.get(k)||'').trim()){$('#form-error').textContent='请补齐必填个人资料。';return;}for(const k of [...Object.keys(labels),'animal','stem'])p[k]=String(f.get(k)||'').trim();for(const k of ['wantedAnimals','wantedStems','hobbies'])p[k]=f.getAll(k);render();$('#dialog').close();};
render();
